package io.knowledgebrain.collaboration;
import java.util.*;import java.io.IOException;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.MeterRegistry;
@RestController
@ConditionalOnProperty(name="brain.collaboration.api.enabled",havingValue="true")
@RequestMapping("/api/groups/{groupId}/studies/{studyId}/discussions")
final class DiscussionController {
 record Catalog(List<DiscussionStore.Summary> items,UUID nextAfter,boolean canWrite) {}
 private final DiscussionStore store;private final StudyController gate;private final MeterRegistry metrics;
 DiscussionController(DiscussionStore store,StudyController gate,MeterRegistry metrics){this.store=store;this.gate=gate;this.metrics=metrics;}
 private boolean writer(StudyController.Access a){return Set.of("OWNER","MEMBER").contains(a.role());}
 private StudyController.Access access(UUID group,HttpServletRequest r,boolean write,String trace){var a=gate.participant(group,r,write,trace);if(write&&!writer(a))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Discussion writer required");return a;}
 static String tag(long v){return "\"di"+v+"\"";}
 static long expected(HttpServletRequest r){var values=Collections.list(r.getHeaders("If-Match"));if(values.isEmpty())throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,"If-Match required");if(values.size()!=1||!values.getFirst().matches("\"di[1-9][0-9]{0,18}\""))throw GroupInput.bad();try{return Long.parseLong(values.getFirst().substring(3,values.getFirst().length()-1));}catch(NumberFormatException e){throw GroupInput.bad();}}
 private String key(HttpServletRequest r){var values=Collections.list(r.getHeaders("Idempotency-Key"));if(values.size()!=1||!values.getFirst().matches("[0-9a-f]{32}"))throw GroupInput.bad();return values.getFirst();}
 private ResponseEntity<?> value(DiscussionStore.Discussion v){return ResponseEntity.ok().eTag(tag(v.version())).cacheControl(CacheControl.noStore()).body(v);}
 private void read(String type){metrics.counter("brain.collaboration.discussion.reads","type",type).increment();}
 private void changed(String type,UUID id,String trace){metrics.counter("brain.collaboration.discussion.changes","type",type).increment();org.slf4j.LoggerFactory.getLogger(getClass()).info("study_discussion type={} aggregate_id={} trace_id={}",type,id,trace.substring(3,35));}
 @GetMapping ResponseEntity<?> list(@PathVariable String groupId,@PathVariable String studyId,HttpServletRequest r)throws IOException{
  gate.query(r,Set.of("after","limit"));gate.empty(r);UUID group=GroupInput.id(groupId),study=GroupInput.id(studyId),after=r.getParameter("after")==null?null:GroupInput.id(r.getParameter("after"));int limit=(int)gate.number(r.getParameter("limit"),20,100);var a=access(group,r,false,gate.trace(r));var page=store.list(group,a.space(),study,after,limit);read("catalog");return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new Catalog(page.items(),page.nextAfter(),writer(a)&&!page.studyArchived()));
 }
 @PostMapping ResponseEntity<?> create(@PathVariable String groupId,@PathVariable String studyId,HttpServletRequest r)throws IOException{
  gate.query(r,Set.of());UUID group=GroupInput.id(groupId),study=GroupInput.id(studyId);String trace=gate.trace(r);var a=access(group,r,true,trace);String key=key(r);var input=GroupInput.settings(gate.jsonBody(r));var result=store.create(group,a.space(),study,a.actor(),key,input.title(),input.description(),trace.substring(3,35));var v=result.discussion();changed(result.created()?"created":"create_replay",v.discussionId(),trace);return ResponseEntity.status(result.created()?201:200).header("Location","/api/groups/"+group+"/studies/"+study+"/discussions/"+v.discussionId()).eTag(tag(v.version())).cacheControl(CacheControl.noStore()).body(v);
 }
 @GetMapping("/{discussionId}") ResponseEntity<?> get(@PathVariable String groupId,@PathVariable String studyId,@PathVariable String discussionId,HttpServletRequest r)throws IOException{gate.query(r,Set.of());gate.empty(r);UUID group=GroupInput.id(groupId),study=GroupInput.id(studyId),id=GroupInput.id(discussionId);var a=access(group,r,false,gate.trace(r));read("current");return value(store.get(group,a.space(),study,id));}
 @PutMapping("/{discussionId}/state") ResponseEntity<?> state(@PathVariable String groupId,@PathVariable String studyId,@PathVariable String discussionId,HttpServletRequest r)throws IOException{gate.query(r,Set.of());UUID group=GroupInput.id(groupId),study=GroupInput.id(studyId),id=GroupInput.id(discussionId);String trace=gate.trace(r);var a=gate.access(group,r,true,trace);long version=expected(r);var v=GroupInput.json(gate.jsonBody(r));if(v==null||!v.isObject()||v.size()!=1||!v.path("state").isString()||!Set.of("OPEN","LOCKED").contains(v.path("state").asString()))throw GroupInput.bad();var result=store.state(group,a.space(),study,id,a.actor(),version,v.path("state").asString(),trace.substring(3,35));changed("state",id,trace);return value(result);}
 @DeleteMapping("/{discussionId}") ResponseEntity<?> retire(@PathVariable String groupId,@PathVariable String studyId,@PathVariable String discussionId,HttpServletRequest r)throws IOException{gate.query(r,Set.of());gate.empty(r);UUID group=GroupInput.id(groupId),study=GroupInput.id(studyId),id=GroupInput.id(discussionId);String trace=gate.trace(r);var a=gate.access(group,r,true,trace);var v=store.state(group,a.space(),study,id,a.actor(),expected(r),"RETIRED",trace.substring(3,35));changed("retired",id,trace);return value(v);}
 @GetMapping("/{discussionId}/revisions") ResponseEntity<?> history(@PathVariable String groupId,@PathVariable String studyId,@PathVariable String discussionId,HttpServletRequest r)throws IOException{gate.query(r,Set.of("before","limit"));gate.empty(r);UUID group=GroupInput.id(groupId),study=GroupInput.id(studyId),id=GroupInput.id(discussionId);long before=gate.number(r.getParameter("before"),Long.MAX_VALUE,Long.MAX_VALUE);int limit=(int)gate.number(r.getParameter("limit"),5,10);var a=access(group,r,false,gate.trace(r));read("history");return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.history(group,a.space(),study,id,before,limit));}
 @PostMapping("/{discussionId}/replies") ResponseEntity<?> reply(@PathVariable String groupId,@PathVariable String studyId,@PathVariable String discussionId,HttpServletRequest r)throws IOException{gate.query(r,Set.of());UUID group=GroupInput.id(groupId),study=GroupInput.id(studyId),id=GroupInput.id(discussionId);String trace=gate.trace(r);var a=access(group,r,true,trace);long version=expected(r);String key=key(r);String content=DiscussionStore.content(gate.jsonBody(r));var result=store.reply(group,a.space(),study,id,a.actor(),version,key,content,trace.substring(3,35));var v=result.reply();changed(result.created()?"replied":"reply_replay",v.replyId(),trace);return ResponseEntity.status(result.created()?201:200).header("Location","/api/groups/"+group+"/studies/"+study+"/discussions/"+id+"/replies/"+v.replyId()).eTag("\"dr1\"").cacheControl(CacheControl.noStore()).body(v);}
 @GetMapping("/{discussionId}/replies") ResponseEntity<?> replies(@PathVariable String groupId,@PathVariable String studyId,@PathVariable String discussionId,HttpServletRequest r)throws IOException{gate.query(r,Set.of("after","limit"));gate.empty(r);UUID group=GroupInput.id(groupId),study=GroupInput.id(studyId),id=GroupInput.id(discussionId),after=r.getParameter("after")==null?null:GroupInput.id(r.getParameter("after"));int limit=(int)gate.number(r.getParameter("limit"),5,10);var a=access(group,r,false,gate.trace(r));read("replies");return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.replies(group,a.space(),study,id,after,limit));}
 @GetMapping("/{discussionId}/replies/{replyId}") ResponseEntity<?> getReply(@PathVariable String groupId,@PathVariable String studyId,@PathVariable String discussionId,@PathVariable String replyId,HttpServletRequest r)throws IOException{gate.query(r,Set.of());gate.empty(r);UUID group=GroupInput.id(groupId),study=GroupInput.id(studyId),id=GroupInput.id(discussionId),reply=GroupInput.id(replyId);var a=access(group,r,false,gate.trace(r));read("reply");return ResponseEntity.ok().eTag("\"dr1\"").cacheControl(CacheControl.noStore()).body(store.getReply(group,a.space(),study,id,reply));}
}
